# Parse dates from all reviews to understand the date range
import re
from datetime import datetime

def parse_date(review_line):
    match = re.search(r'Date: (\w+ \d+, \d+)', review_line)
    if match:
        date_str = match.group(1)
        try:
            return datetime.strptime(date_str, '%b %d, %Y')
        except:
            return None
    return None

# Get all dates
dates = []
for line in review_lines:
    d = parse_date(line)
    if d:
        dates.append(d)

print(f"Parsed {len(dates)} dates")
print(f"Date range: {min(dates)} to {max(dates)}")

# Filter to date range: Jan 18, 2023 to Nov 09, 2024 inclusive
start_date = datetime(2023, 1, 18)
end_date = datetime(2024, 11, 9)

filtered_reviews = []
for line in review_lines:
    d = parse_date(line)
    if d and start_date <= d <= end_date:
        filtered_reviews.append((d, line))

print(f"\nFiltered reviews in date range: {len(filtered_reviews)}")
print(f"Date range of filtered: {min(r[0] for r in filtered_reviews)} to {max(r[0] for r in filtered_reviews)}")
